 const loose=(Array.isArray(input.loose)?input.loose:[]).slice(0,64).map((b,i)=>({id:text(b.id)||'restored-'+i,payload:cleanCarry(b.payload),position:{x:Number(b.position?.x),y:Number(b.position?.y),z:Number(b.position?.z)},shape:{width:Math.max(.025,num(b.shape?.width||.25,1)),depth:Math.max(.025,num(b.shape?.depth||.25,1)),height:Math.max(.035,num(b.shape?.height||.25,1.5))},velocity:Math.max(-15,Math.min(0,Number(b.velocity)||0)),tableId:text(b.tableId)})).filter(b=>b.payload&&Object.values(b.position).every(Number.isFinite));
